import math
import base64
import numpy as np
import pandas as pd
import streamlit as st
from model import simulate

MANUAL_CIRCUIT = ""

st.set_page_config(page_title="Electrical Quantities Lab", page_icon="⚡", layout="wide")
st.title("⚡ Experiment 3 · Electrical Quantities")
st.caption("Voltage, current, power and power factor in a single-phase RLC circuit")
st.info("Virtual readings are ideal simulations. Laboratory mode uses readings you enter; this app does not connect to instruments.")
if "rows" not in st.session_state:
    st.session_state.rows = []
mode = st.sidebar.radio("Choose mode", ["Virtual experiment", "Laboratory readings"])
st.sidebar.caption("Dr. Arivoli S · EEE · PSG iTech")
learn, formulas, work, record = st.tabs(["Aim & circuit diagram", "Calculation formulas", "Perform experiment", "Observation table & result"])
with learn:
    st.subheader("Aim")
    st.write("Measure voltage, current, active power and power factor in a single-phase RLC circuit; compare wattmeter power with VI cos φ.")
    st.write("Apparatus: 0–2 A AC ammeter, 0–300 V AC voltmeter, single-phase wattmeter, power-factor meter, RLC load and connecting wires.")
    st.subheader("Circuit diagram from the laboratory manual")
    st.image(base64.b64decode(MANUAL_CIRCUIT), caption="Original circuit diagram, EPL lab manual, PDF page 12; handwritten annotations retained.")
    st.caption("Ph = phase; N = neutral. Current coils are in series; voltage coils and voltmeter are across the supply. The LOAD block represents the selected RLC connection.")
    st.markdown("1. Set the supply OFF and obtain faculty approval for physical wiring.\n2. Connect current coils in series; voltmeter and voltage coils across supply.\n3. For the virtual experiment choose topology and R, L, C; switch the virtual supply ON.\n4. Note V, I, wattmeter power and PF; save an observation.\n5. Repeat with different loads. Switch supply OFF before physical changes.\n6. Compare wattmeter readings with calculated power and download the table.")
    st.latex(r"S=VI,\quad P=VI\cos\phi,\quad Q=VI\sin\phi,\quad S^2=P^2+Q^2")
    st.write("Q is positive for lagging (inductive) loads and negative for leading (capacitive) loads. PF at zero apparent power is undefined.")
    with st.expander("Viva preparation"):
        st.write("Apparent power: VI in VA. Active power: VI cos φ in W. Reactive power: VI sin φ in var. Maximum PF is 1. RLC denotes resistance, inductance and capacitance. In series resonance XL = XC and PF = 1 for an ideal load with R > 0.")

with formulas:
    st.subheader("Formulas for calculation")
    st.write("V and I are RMS readings; f is in Hz, R in Ω, L in henry and C in farad. Wₘ denotes the wattmeter reading in watts; PFₘ denotes the power-factor meter reading.")
    st.markdown("**1. Apparent, active and reactive power — manual formulas**")
    st.latex(r"S=VI\quad[\mathrm{VA}]")
    st.latex(r"P_{calc}=VI\cos\phi=VI\,PF_m\quad[\mathrm{W}]")
    st.latex(r"PF=\cos\phi,\qquad Q=VI\sin\phi\quad[\mathrm{var}]")
    st.markdown("**2. Formulas from meter readings**")
    st.latex(r"PF_{from\ wattmeter}=\frac{W_m}{VI},\qquad |\phi|=\cos^{-1}(PF_m)")
    st.latex(r"Q=\sigma VI\sqrt{1-PF_m^2},\qquad \sigma=+1\ (lagging),\ -1\ (leading)")
    st.latex(r"S^2=P^2+Q^2,\qquad |Q|=\sqrt{S^2-P^2}")
    st.latex(r"\mathrm{Difference}=W_m-P_{calc},\qquad \mathrm{Error}(\%)=\frac{|W_m-P_{calc}|}{|P_{calc}|}\times100")
    st.caption("Power factor from Wₘ/(VI) is undefined at VI = 0. Percentage error is undefined at calculated P = 0. Meter magnitudes alone cannot determine leading/lagging; select it from the circuit or phase measurement. Unity PF gives Q = 0.")
    st.markdown("**3. Unit conversions and reactances**")
    st.latex(r"L[H]=L[mH]\times10^{-3},\quad C[F]=C[\mu F]\times10^{-6},\quad \omega=2\pi f")
    st.latex(r"X_L=\omega L,\qquad X_C=\frac{1}{\omega C}")
    st.markdown("**4. Series RLC calculation**")
    st.latex(r"X=X_L-X_C,\quad Z=R+jX,\quad |Z|=\sqrt{R^2+X^2},\quad I=\frac{V}{|Z|}")
    st.latex(r"\phi=\tan^{-1}\left(\frac{X}{R}\right),\quad PF=\frac{R}{|Z|},\quad P=I^2R,\quad Q=I^2X")
    st.markdown("**5. Parallel RLC calculation — separate ideal branches**")
    st.latex(r"G=\frac{1}{R},\quad B=\omega C-\frac{1}{\omega L},\quad Y=G+jB,\quad |Y|=\sqrt{G^2+B^2}")
    st.latex(r"I=V|Y|,\quad I_R=V/R,\quad I_L=V/X_L,\quad I_C=V/X_C")
    st.latex(r"\phi=-\tan^{-1}(B/G),\quad PF=G/|Y|,\quad P=V^2/R,\quad Q=-V^2B")
    st.markdown("**6. Ideal resonance**")
    st.latex(r"X_L=X_C,\qquad f_0=\frac{1}{2\pi\sqrt{LC}},\qquad PF=1,\quad Q=0")
    st.write("Signed phase convention: positive φ means current lags voltage; negative φ means it leads. All calculations assume sinusoidal steady state and ideal components.")
    st.markdown("**Worked example using laboratory readings**")
    st.write("V = 230 V, I = 1 A, PF = 0.8 lagging, Wₘ = 180 W.")
    st.latex(r"S=230\times1=230\ VA,\quad P_{calc}=230\times1\times0.8=184\ W")
    st.latex(r"\phi=\cos^{-1}(0.8)=36.87^\circ,\quad Q=230\sqrt{1-0.8^2}=138\ var")
    st.latex(r"PF_{from\ wattmeter}=180/230=0.7826,\quad Error=100\times|180-184|/184=2.174\%")

with work:
    if mode == "Virtual experiment":
        left, right = st.columns([1, 2])
        with left:
            topology = st.selectbox("RLC connection", ["Series", "Parallel"])
            v = st.number_input("Supply RMS voltage (V)", 0.0, 300.0, 230.0)
            f = st.number_input("Frequency (Hz)", 1.0, 1000.0, 50.0)
            r = st.number_input("Resistance (Ω)", 1.0, 10000.0, 200.0)
            l = st.number_input("Inductance (mH)", 1.0, 10000.0, 500.0)
            c = st.number_input("Capacitance (µF)", 0.1, 10000.0, 20.0)
            on = st.toggle("Virtual supply ON", value=False)
        d = simulate(v if on else 0, f, r, l, c, topology)
        with right:
            cols = st.columns(4)
            for col, title, value in zip(cols, ["Voltmeter", "Ammeter", "Wattmeter", "PF meter"], [f'{d["V"]:.2f} V', f'{d["I"]:.3f} A', f'{d["P"]:.2f} W', "Undefined" if d["PF"] is None else f'{d["PF"]:.3f}']):
                col.metric(title, value)
            st.write(f'{d["nature"]} · phase angle {d["phi"]:.2f}° · S = {d["S"]:.2f} VA · Q = {d["Q"]:.2f} var')
            if d["I"] > 2:
                st.warning("Current exceeds the manual's 2 A ammeter range. This is a simulation only; choose a load within the actual equipment ratings.")
            if on and v > 0:
                t = np.linspace(0, 2/f, 400)
                st.line_chart(pd.DataFrame({"Time (s)": t, "Voltage / Vpeak": np.sin(2*np.pi*f*t), "Current / Ipeak": np.sin(2*np.pi*f*t-math.radians(d["phi"]))}).set_index("Time (s)"))
                st.caption("Normalized waveforms, two cycles. Voltage and current share unit amplitude to show their phase relationship.")
            st.latex(r"Z_{series}=R+j(\omega L-1/(\omega C)),\quad Y_{parallel}=1/R+j(\omega C-1/(\omega L))")
        if st.button("Save virtual observation", disabled=not on or v == 0):
            st.session_state.rows.append({"Mode": "Simulated", "Connection": topology, "R (ohm)": r, "L (mH)": l, "C (uF)": c, "f (Hz)": f, "I (A)": d["I"], "V (V)": v, "PF": d["PF"], "Nature": d["nature"], "Calculated P (W)": d["P"], "Wattmeter P (W)": d["P"], "S (VA)": d["S"], "Q (var)": d["Q"], "Error (%)": 0.0})
            st.success("Observation saved. Ideal meters agree exactly.")
    else:
        st.subheader("Enter actual meter readings")
        with st.form("measured"):
            v = st.number_input("Voltmeter (V)", 0.0, value=230.0)
            i = st.number_input("Ammeter (A)", 0.0, value=1.0)
            pf = st.number_input("Power-factor meter", 0.0, 1.0, 0.8)
            p = st.number_input("Wattmeter (W)", 0.0, value=184.0)
            nature = st.selectbox("PF nature", ["Lagging", "Leading", "Unity"])
            save = st.form_submit_button("Calculate and save reading")
        if save:
            s = v*i
            if s == 0 or p > s + 1e-6 or (nature == "Unity" and abs(pf-1) > 1e-6):
                st.error("Check inputs: VI must be positive, wattmeter power cannot exceed VI for this passive load, and Unity requires PF = 1.")
            else:
                pc = s*pf
                q = s*math.sqrt(max(0, 1-pf*pf)) * (-1 if nature == "Leading" else 1)
                error = 100*abs(p-pc)/pc if pc else None
                st.session_state.rows.append({"Mode": "Measured", "Connection": "User laboratory load", "I (A)": i, "V (V)": v, "PF": pf, "Nature": nature, "Calculated P (W)": pc, "Wattmeter P (W)": p, "S (VA)": s, "Q (var)": q, "Error (%)": error})
                st.success(f"Calculated P = {pc:.2f} W; S = {s:.2f} VA; Q = {q:.2f} var. Reading saved.")
with record:
    st.caption("Readings remain in this browser session only. Download before refreshing or closing; no student database is included.")
    if st.session_state.rows:
        df = pd.DataFrame(st.session_state.rows)
        df.index = np.arange(1, len(df)+1)
        df.index.name = "S.No."
        st.dataframe(df)
        st.download_button("Download observation CSV", df.to_csv().encode(), "experiment3_observations.csv", "text/csv")
        report = "Experiment 3: Electrical quantities\n\n" + df.to_string() + "\n\nCalculated power = VI PF. Error (%) = 100 |W - VI PF| / (VI PF); undefined when calculated power is zero.\nSimulated rows use ideal meters; measured rows are user-entered laboratory observations.\nResult: Voltage, current, power and power factor were recorded and active power compared. Interpret measured differences using instrument accuracy and reading uncertainty.\n"
        st.download_button("Download text report", report, "experiment3_report.txt")
        if st.button("Clear all observations"):
            st.session_state.rows = []
            st.rerun()
    else:
        st.write("Save your first observation in Perform experiment.")
